import{_ as e,o,c as i,a2 as a}from"./chunks/framework.CPHNBVkq.js";const r="/corbi/screenshots/notifications.png",d=JSON.parse('{"title":"Notifications & Daily Summary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notifications.md","filePath":"guide/notifications.md"}'),s={name:"guide/notifications.md"};function n(m,t,u,h,l,c){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="notifications-daily-summary" tabindex="-1">Notifications &amp; Daily Summary <a class="header-anchor" href="#notifications-daily-summary" aria-label="Permalink to &quot;Notifications &amp; Daily Summary&quot;">​</a></h1><p>Rather than interrupting you throughout the day, Corbi can send a single <strong>Daily Summary</strong> email recapping your <a href="./pulse-feed.html">Pulse feed</a>. You choose whether to receive it, what time it arrives, and which time zone that time is based on.</p><p>Find these options under <strong>Settings → Notification Preferences</strong>.</p><p><img src="'+r+'" alt="Notification preferences"></p><h2 id="turn-the-daily-summary-on-or-off" tabindex="-1">Turn the Daily Summary on or off <a class="header-anchor" href="#turn-the-daily-summary-on-or-off" aria-label="Permalink to &quot;Turn the Daily Summary on or off&quot;">​</a></h2><p>At the top of Notification Preferences is <strong>Receive Daily Summary</strong> — &quot;Get a summary of the content you want to see every day at the same time.&quot;</p><p>Toggle it <strong>on</strong> to start receiving the summary by email, or <strong>off</strong> to stop. When it&#39;s off, the time and time zone options are hidden because they aren&#39;t needed.</p><h2 id="set-your-summary-time" tabindex="-1">Set your summary time <a class="header-anchor" href="#set-your-summary-time" aria-label="Permalink to &quot;Set your summary time&quot;">​</a></h2><p>With the Daily Summary on, use the <strong>Daily Summary Time</strong> slider to pick the hour you want your summary to arrive. Slide to the hour that works best for you — for example, first thing in the morning.</p><p>Your choice is saved automatically a moment after you stop adjusting the slider.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pick a time when you&#39;ll actually read it. Many people choose the start of their workday so the summary is waiting for them.</p></div><h2 id="time-zone" tabindex="-1">Time zone <a class="header-anchor" href="#time-zone" aria-label="Permalink to &quot;Time zone&quot;">​</a></h2><p>The <strong>Timezone</strong> setting controls the clock your summary time is based on — &quot;Daily summary will be sent based on this timezone.&quot; Select your region from the list.</p><p>Corbi sets this automatically from your device the first time you sign in, so you usually won&#39;t need to change it. Update it if you move or travel and want your summary to follow a different zone.</p><div class="warning custom-block"><p class="custom-block-title">Daylight saving time</p><p>If a daylight saving change shifts your usual summary time, Corbi shows a notice asking you to confirm your preferred time. Just re-check the <strong>Daily Summary Time</strong> slider and it&#39;ll be saved again.</p></div><h2 id="where-this-lives" tabindex="-1">Where this lives <a class="header-anchor" href="#where-this-lives" aria-label="Permalink to &quot;Where this lives&quot;">​</a></h2><p>You can reach Notification Preferences any time from <strong>Settings</strong>. See <a href="./settings.html">Settings</a> for the full list of options in that area.</p>',17)])])}const f=e(s,[["render",n]]);export{d as __pageData,f as default};
